using namespace std;

class Solution {
public:
    vector<long long> findMaxSum(vector<int>& nums1, vector<int>& nums2, int k) {
        int n = nums1.size();
        vector<tuple<int, int, int>> arr(n);
        for (int i = 0; i < n; i++) {
            arr[i] = {nums1[i], nums2[i], i};
        }
        sort(arr.begin(), arr.end());

        vector<long long> ans(n, 0);
        priority_queue<int, vector<int>, greater<int>> minHeap;
        long long currentSum = 0;

        int i = 0;
        while (i < n) {
            int j = i;
            while (j < n && get<0>(arr[j]) == get<0>(arr[i])) {
                j++;
            }
            for (int idx = i; idx < j; idx++) {
                ans[get<2>(arr[idx])] = currentSum;
            }
            for (int idx = i; idx < j; idx++) {
                int val2 = get<1>(arr[idx]);
                currentSum += val2;
                minHeap.push(val2);
                if ((int)minHeap.size() > k) {
                    currentSum -= minHeap.top();
                    minHeap.pop();
                }
            }
            i = j;
        }
        return ans;
    }
};

import java.util.Arrays;
import java.util.PriorityQueue;

class Solution {
    public long[] findMaxSum(int[] nums1, int[] nums2, int k) {
        int n = nums1.length;
        Integer[] order = new Integer[n];
        for (int i = 0; i < n; i++) order[i] = i;
        Arrays.sort(order, (a, b) -> Integer.compare(nums1[a], nums1[b]));

        long[] ans = new long[n];
        PriorityQueue<Integer> minHeap = new PriorityQueue<>();
        long currentSum = 0;

        int i = 0;
        while (i < n) {
            int j = i;
            while (j < n && nums1[order[j]] == nums1[order[i]]) {
                j++;
            }
            for (int idx = i; idx < j; idx++) {
                ans[order[idx]] = currentSum;
            }
            for (int idx = i; idx < j; idx++) {
                int val2 = nums2[order[idx]];
                currentSum += val2;
                minHeap.offer(val2);
                if (minHeap.size() > k) {
                    currentSum -= minHeap.poll();
                }
            }
            i = j;
        }
        return ans;
    }
}

