var findMaxSum = function(nums1, nums2, k) {
    const n = nums1.length;
    const order = Array.from({ length: n }, (_, i) => i);
    order.sort((a, b) => nums1[a] - nums1[b]);

    const ans = new Array(n).fill(0);
    const minHeap = [];
    let currentSum = 0;

    function pushHeap(val) {
        minHeap.push(val);
        minHeap.sort((a, b) => a - b);
    }

    intLoop:
    for (let i = 0; i < n; ) {
        let j = i;
        while (j < n && nums1[order[j]] === nums1[order[i]]) {
            j++;
        }
        for (let idx = i; idx < j; idx++) {
            ans[order[idx]] = currentSum;
        }
        for (let idx = i; idx < j; idx++) {
            const val2 = nums2[order[idx]];
            currentSum += val2;
            pushHeap(val2);
            if (minHeap.length > k) {
                currentSum -= minHeap.shift();
            }
        }
        i = j;
    }
    return ans;
